def count_up_to(n):
    """Implement a function that takes a non-negative integer and returns an array of the prime numbers less than n."""
    if n < 2:
        return []
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n : i] = [False] * len(sieve[i*i : n : i])
    primes = [i for i, is_prime in enumerate(sieve) if is_prime]
    return primes
